# -*- coding: utf-8 -*-
"""Telas (HTML) e estilo (CSS) embutidos no código. Ao iniciar, o sistema confere as pastas templates/ e static/ e recria
qualquer arquivo ausente, vazio ou diferente, evitando telas em branco por arquivos .html corrompidos no download."""
import os

TEMPLATES = {
    'pagina': '<!doctype html>\n<html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">\n<title>Efemérides transmitidas × precisas</title>\n<link rel="stylesheet" href="{{ url_for(\'static\', filename=\'estilo.css\') }}"><style>\n.tabs{display:flex;gap:7px;margin-top:14px;flex-wrap:wrap}\n.tabs .tab{display:flex;align-items:center;gap:8px;padding:8px 13px 8px 10px;border-radius:12px;text-decoration:none;color:#cfe3ee;background:rgba(255,255,255,.07);border:1px solid rgba(255,255,255,.2);transition:all .15s}\n.tabs .tab:hover{background:rgba(255,255,255,.17);color:#fff;transform:translateY(-1px)}\n.tabs .tab svg{width:21px;height:21px;flex:none}\n.tabs .tab .tt{line-height:1.2}\n.tabs .tab b{display:block;font-size:13px}\n.tabs .tab.on{background:#fff;color:#12384f;border-color:#fff;box-shadow:0 4px 14px rgba(0,0,0,.28)}\n.tt3 th,.tt3 td{text-align:left;white-space:normal}.tt3 td:last-child{font-weight:600;white-space:nowrap}\n.cx{background:#eef5fa;border-left:4px solid #12384f;border-radius:6px;padding:8px 14px}\n</style>\n</head><body>\n<header><h1>Efemérides transmitidas × precisas</h1><span>Posição de satélites GNSS · comparação com SP3</span>\n<nav class="tabs"><a class="tab on" href="/" title="Posição de satélites: efemérides transmitidas × precisas"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="3.2"/><ellipse cx="12" cy="12" rx="10" ry="4.2" transform="rotate(-30 12 12)"/><circle cx="19.2" cy="7.8" r="1.3" fill="currentColor"/></svg><div class="tt"><b>Efemérides</b></div></a><a class="tab" href="/obs" title="Qualidade das observáveis L1/L2 e saltos de ciclo"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"><path d="M2 12h3.5l2.5-7 4 14 3-10 2 3H22"/></svg><div class="tt"><b>Observáveis</b></div></a><a class="tab" href="/qc" title="Completude, multipath, SNR e saltos de ciclo"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"><path d="M12 3l7 3v5c0 4.5-3 8-7 10-4-2-7-5.5-7-10V6z"/><path d="M8.5 12.2l2.5 2.5 4.5-5"/></svg><div class="tt"><b>Qualidade (TEQC)</b></div></a><a class="tab" href="/rinex" title="Cortar sessões, filtrar GPS e L1/C1 (como o teqc)"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"><circle cx="6" cy="6.5" r="2.4"/><circle cx="6" cy="17.5" r="2.4"/><path d="M8 8l12 8M8 16L20 8"/></svg><div class="tt"><b>Editar RINEX</b></div></a><a class="tab" href="/ppp" title="Resultados do IBGE-PPP: σ3D, convergência, comparações"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="8"/><circle cx="12" cy="12" r="3"/><path d="M12 2v4M12 18v4M2 12h4M18 12h4"/></svg><div class="tt"><b>PPP (IBGE)</b></div></a><a class="tab" href="/polo" title="xp, yp a partir do Boletim B do IERS"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="9"/><path d="M12 3v18M3 12h18" opacity=".45"/><path d="M12 12c1.5-3 4.5-3.2 4.5-.5S13 14 12.2 11"/><circle cx="15" cy="9.5" r="1.3" fill="currentColor"/></svg><div class="tt"><b>Movimento do polo</b></div></a><a class="tab" href="/tempo" title="UTC, UT1, TAI, TGPS, TT, Data Juliana, semana GPS"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="9"/><path d="M12 6.5V12l3.5 2.2"/></svg><div class="tt"><b>Sistemas de tempo</b></div></a></nav></header>\n<main>\n{% for m in get_flashed_messages() %}<div class="aviso erro">{{ m }}</div>{% endfor %}\n\n{% if not sid %}\n<section class="card"><h2>1. Carregar arquivos</h2>\n<form action="{{ url_for(\'enviar\') }}" method="post" enctype="multipart/form-data">\n<label>Arquivo de navegação (RINEX .n / .14l / .rnx)<input type="file" name="nav"></label>\n<label>Efemérides precisas (.sp3)<input type="file" name="sp3"></label>\n<div class="acoes"><button>Carregar</button>\n<button name="exemplo" value="1" class="sec" formnovalidate>Usar arquivos de exemplo (Galileo E19, 22/07/2014)</button></div>\n</form></section>\n{% else %}\n<section class="card"><h2>2. Parâmetros do cálculo</h2>\n<form method="post" id="fm">\n<div class="grade">\n<label>Satélite<select id="sat">{% for s in sats %}<option>{{ s }}</option>{% endfor %}</select></label>\n<label>Efeméride (registro)<select id="reg" name="reg"></select></label>\n<label>Início (tempo GPS)<input type="datetime-local" id="inicio" name="inicio" required value="{{ f.get(\'inicio\',\'\') }}"></label>\n<label>Passo (min)<input type="number" name="passo" step="any" min="0.1" value="{{ f.get(\'passo\', 15) }}"></label>\n<label>Nº de épocas<input type="number" name="n" min="2" max="500" value="{{ f.get(\'n\', 9) }}"></label>\n<label class="chk"><input type="checkbox" name="terra" {{ \'checked\' if \'terra\' in f }}> Mostrar a Terra no gráfico 3D</label>\n<label class="chk"><input type="checkbox" name="sem_dts" {{ \'checked\' if \'sem_dts\' in f }}> Não aplicar dts (usar a época como tempo GPS)</label>\n<label class="chk"><input type="checkbox" name="gm_icd" {{ \'checked\' if \'gm_icd\' in f }}> GM do ICD do GPS (3,986005e14)</label>\n</div>\n{% if not tem_sp3 %}<div class="aviso">Nenhum SP3 carregado: só serão calculadas as coordenadas.</div>{% endif %}\n<div class="acoes"><button>Calcular</button><a class="btn sec" href="{{ url_for(\'index\') }}">Trocar arquivos</a></div>\n</form></section>\n<div id="dados" hidden data-regs=\'{{ regs|tojson }}\' data-reg="{{ f.get(\'reg\',\'\') }}"></div>\n<script>\nconst D=document.getElementById(\'dados\'), REGS=JSON.parse(D.dataset.regs), regAnt=D.dataset.reg;\nconst sat=document.getElementById(\'sat\'), reg=document.getElementById(\'reg\'), ini=document.getElementById(\'inicio\');\nfunction fill(){reg.innerHTML=\'\';REGS.filter(r=>r.sat===sat.value).forEach(r=>reg.add(new Option(r.rot,r.i)));}\nfunction setIni(){const r=REGS.find(x=>x.i==reg.value);if(r)ini.value=r.toc;}\nsat.onchange=()=>{fill();setIni();};reg.onchange=setIni;\nconst ra=REGS.find(r=>String(r.i)===regAnt);if(ra)sat.value=ra.sat;\nfill();if(ra)reg.value=regAnt;if(!ini.value)setIni();\n</script>\n\n{% if res %}\n<section class="card"><h2>3. Resultados — {{ res.sat }}</h2>\n<div class="chips"><span>Semana GPS <b>{{ res.semana }}</b></span><span>Dia GPS <b>{{ res.dow }}</b></span>\n<span>DOY <b>{{ res.doy }}</b></span><span>Início <b>{{ res.ini.strftime(\'%d/%m/%Y %H:%M\') }}</b></span>\n<span>Passo <b>{{ res.passo }} min</b></span><span>Épocas <b>{{ res.n }}</b></span><span>GM <b>{{ res.gm }}</b></span><span>dts <b>{{ \'aplicado\' if res.dts else \'não aplicado\' }}</b></span></div>\n{% for a in res.avisos %}<div class="aviso">{{ a }}</div>{% endfor %}\n{% if res.resumo %}<p class="resumo">{{ res.resumo }}</p>{% endif %}\n<h3>Coordenadas e discrepâncias (transmitida − SP3)</h3>\n<div class="rolar"><table><tr>{% for c in cab %}<th>{{ c }}</th>{% endfor %}</tr>\n{% for r in res.rows %}<tr>{% for c in r %}<td>{{ c }}</td>{% endfor %}</tr>{% endfor %}</table></div>\n{% if res.est %}<h3>Estatísticas das discrepâncias (m)</h3>\n<table class="peq"><tr><th></th><th>Média</th><th>RMS</th><th>Máx |d|</th></tr>\n{% for e in res.est %}<tr><td>{{ e[0] }}</td><td>{{ e[1] }}</td><td>{{ e[2] }}</td><td>{{ e[3] }}</td></tr>{% endfor %}</table>{% endif %}\n<div class="acoes"><a class="btn" href="{{ url_for(\'baixar\', sid=sid, what=\'csv\') }}">Baixar CSV</a></div>\n<h3>Gráficos</h3>\n{% for b in res.b64 %}{% if b %}<figure><img src="data:image/png;base64,{{ b }}" alt="Gráfico {{ loop.index }}">\n<a class="btn sec" href="{{ url_for(\'baixar\', sid=sid, what=\'g\' ~ loop.index) }}">Baixar PNG</a></figure>{% endif %}{% endfor %}\n<h3>Parâmetros extraídos da efeméride</h3>\n<table class="peq"><tr><th>Parâmetro</th><th>Valor</th><th>Unid.</th></tr>\n{% for a,v,u in res.params %}<tr><td>{{ a }}</td><td>{{ v }}</td><td>{{ u }}</td></tr>{% endfor %}</table>\n<h3>Trecho do arquivo de navegação (para o apêndice)</h3><pre>{{ res.raw }}</pre>\n</section>{% endif %}\n{% endif %}\n</main></body></html>\n',
    'obs': '<!doctype html>\n<html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">\n<title>Qualidade das observáveis GNSS</title>\n<link rel="stylesheet" href="{{ url_for(\'static\', filename=\'estilo.css\') }}"><style>\n.tabs{display:flex;gap:7px;margin-top:14px;flex-wrap:wrap}\n.tabs .tab{display:flex;align-items:center;gap:8px;padding:8px 13px 8px 10px;border-radius:12px;text-decoration:none;color:#cfe3ee;background:rgba(255,255,255,.07);border:1px solid rgba(255,255,255,.2);transition:all .15s}\n.tabs .tab:hover{background:rgba(255,255,255,.17);color:#fff;transform:translateY(-1px)}\n.tabs .tab svg{width:21px;height:21px;flex:none}\n.tabs .tab .tt{line-height:1.2}\n.tabs .tab b{display:block;font-size:13px}\n.tabs .tab.on{background:#fff;color:#12384f;border-color:#fff;box-shadow:0 4px 14px rgba(0,0,0,.28)}\n.tt3 th,.tt3 td{text-align:left;white-space:normal}.tt3 td:last-child{font-weight:600;white-space:nowrap}\n.cx{background:#eef5fa;border-left:4px solid #12384f;border-radius:6px;padding:8px 14px}\n</style>\n</head><body>\n<header><h1>Qualidade das observáveis GNSS (L1/L2)</h1><span>RINEX de observação da RBMC · Lc, Lg, Pc e saltos de ciclo</span>\n<nav class="tabs"><a class="tab" href="/" title="Posição de satélites: efemérides transmitidas × precisas"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="3.2"/><ellipse cx="12" cy="12" rx="10" ry="4.2" transform="rotate(-30 12 12)"/><circle cx="19.2" cy="7.8" r="1.3" fill="currentColor"/></svg><div class="tt"><b>Efemérides</b></div></a><a class="tab on" href="/obs" title="Qualidade das observáveis L1/L2 e saltos de ciclo"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"><path d="M2 12h3.5l2.5-7 4 14 3-10 2 3H22"/></svg><div class="tt"><b>Observáveis</b></div></a><a class="tab" href="/qc" title="Completude, multipath, SNR e saltos de ciclo"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"><path d="M12 3l7 3v5c0 4.5-3 8-7 10-4-2-7-5.5-7-10V6z"/><path d="M8.5 12.2l2.5 2.5 4.5-5"/></svg><div class="tt"><b>Qualidade (TEQC)</b></div></a><a class="tab" href="/rinex" title="Cortar sessões, filtrar GPS e L1/C1 (como o teqc)"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"><circle cx="6" cy="6.5" r="2.4"/><circle cx="6" cy="17.5" r="2.4"/><path d="M8 8l12 8M8 16L20 8"/></svg><div class="tt"><b>Editar RINEX</b></div></a><a class="tab" href="/ppp" title="Resultados do IBGE-PPP: σ3D, convergência, comparações"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="8"/><circle cx="12" cy="12" r="3"/><path d="M12 2v4M12 18v4M2 12h4M18 12h4"/></svg><div class="tt"><b>PPP (IBGE)</b></div></a><a class="tab" href="/polo" title="xp, yp a partir do Boletim B do IERS"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="9"/><path d="M12 3v18M3 12h18" opacity=".45"/><path d="M12 12c1.5-3 4.5-3.2 4.5-.5S13 14 12.2 11"/><circle cx="15" cy="9.5" r="1.3" fill="currentColor"/></svg><div class="tt"><b>Movimento do polo</b></div></a><a class="tab" href="/tempo" title="UTC, UT1, TAI, TGPS, TT, Data Juliana, semana GPS"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="9"/><path d="M12 6.5V12l3.5 2.2"/></svg><div class="tt"><b>Sistemas de tempo</b></div></a></nav></header>\n<main>\n{% for m in get_flashed_messages() %}<div class="aviso erro">{{ m }}</div>{% endfor %}\n{% if not sid %}\n<section class="card"><h2>1. Carregar arquivos</h2>\n<form action="{{ url_for(\'obs_enviar\') }}" method="post" enctype="multipart/form-data">\n<label>Arquivos de observação (.zip do IBGE, .d/.o, .gz) — pode selecionar vários (estações e dias)\n<input type="file" name="arquivos" multiple required></label>\n<p>Lê o .zip como baixado da RBMC, identifica o arquivo de observação pelo cabeçalho e descompacta o Hatanaka (CRINEX) automaticamente. Só observáveis GPS.</p>\n<div class="acoes"><button>Processar</button></div></form></section>\n{% else %}\n<section class="card"><h2>2. Parâmetros</h2>\n<form method="post"><div class="grade">\n<label>Arquivo<select name="arq">{% for i,n,e in arqs %}<option value="{{ i }}" {{ \'selected\' if i==res.idx }}>{{ e }} · {{ n }}</option>{% endfor %}</select></label>\n<label>Satélite (séries)<select name="sat">{% for s in sats %}<option {{ \'selected\' if s==res.sat }}>{{ s }}</option>{% endfor %}</select></label>\n<label>Limiar de salto de ciclo em ΔLg (m)<input type="number" name="limiar" step="0.01" min="0.01" value="{{ res.limiar }}"></label>\n{% if res.est|length >= 2 %}<label>Estação A (comparação)<select name="estA">{% for e in res.est %}<option {{ \'selected\' if res.comp and e==res.comp.ea }}>{{ e }}</option>{% endfor %}</select></label>\n<label>Estação B (comparação)<select name="estB">{% for e in res.est %}<option {{ \'selected\' if res.comp and e==res.comp.eb }}>{{ e }}</option>{% endfor %}</select></label>{% endif %}</div>\n<p>Observáveis usadas (fase L1, fase L2, código 1, código 2): {{ res.obs|join(\' · \') }}</p>\n<div class="acoes"><button>Atualizar</button><a class="btn sec" href="{{ url_for(\'obs_index\') }}">Trocar arquivos</a></div></form></section>\n<section class="card"><h2>3. Resumo por arquivo</h2>\n<div class="rolar"><table><tr>{% for c in cab %}<th>{{ c }}</th>{% endfor %}</tr>\n{% for r in res.resumo %}<tr>{% for c in r %}<td>{{ c }}</td>{% endfor %}</tr>{% endfor %}</table></div>\n<p>Lg = Φ1 − Φ2; Lc = (f1²Φ1 − f2²Φ2)/(f1² − f2²); Pc análoga com P1, P2. Salto: |ΔLg| entre épocas consecutivas acima do limiar; taxa = saltos / comparações possíveis.</p>\n<div class="acoes"><a class="btn" href="{{ url_for(\'obs_baixar\', sid=sid, what=\'resumo\') }}">Baixar resumo (CSV)</a>\n<a class="btn" href="{{ url_for(\'obs_baixar\', sid=sid, what=\'dados\') }}">Baixar dados do arquivo selecionado (CSV)</a></div>\n{% for t,b in res.figs %}<h3>{{ t }}</h3><figure><img src="data:image/png;base64,{{ b }}" alt="{{ t }}">\n<a class="btn sec" href="{{ url_for(\'obs_baixar\', sid=sid, what=\'g\' ~ loop.index) }}">Baixar PNG</a></figure>{% endfor %}</section>\n<section class="card"><h2>4. Comparação entre estações{% if res.comp %}: {{ res.comp.ea }} × {{ res.comp.eb }}{% endif %}</h2>\n{% if res.comp %}<p>Agrega todos os arquivos (dias) de cada estação. Diferença A − B na última linha.</p>\n<div class="rolar"><table><tr>{% for c in res.comp.cab %}<th>{{ c }}</th>{% endfor %}</tr>\n{% for r in res.comp.rows %}<tr>{% for c in r %}<td>{{ c }}</td>{% endfor %}</tr>{% endfor %}</table></div>\n<div class="acoes"><a class="btn" href="{{ url_for(\'obs_baixar\', sid=sid, what=\'comp\') }}">Baixar comparação (CSV)</a></div>\n{% for t,b in res.comp.figs %}<h3>{{ t }}</h3><figure><img src="data:image/png;base64,{{ b }}" alt="{{ t }}">\n<a class="btn sec" href="{{ url_for(\'obs_baixar\', sid=sid, what=\'c\' ~ loop.index) }}">Baixar PNG</a></figure>{% endfor %}\n{% else %}<p class="aviso">Para comparar, envie de uma só vez os arquivos de <b>duas estações</b> (por exemplo, o zip de Belém e o de São Paulo; pode ser vários dias de cada uma). A comparação aparece aqui automaticamente.</p>{% endif %}</section>\n{% endif %}\n</main></body></html>\n',
    'qc': '<!doctype html>\n<html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">\n<title>Controle de qualidade (estilo TEQC)</title>\n<link rel="stylesheet" href="{{ url_for(\'static\', filename=\'estilo.css\') }}">\n<style>\n.tabs{display:flex;gap:7px;margin-top:14px;flex-wrap:wrap}\n.tabs .tab{display:flex;align-items:center;gap:8px;padding:8px 13px 8px 10px;border-radius:12px;text-decoration:none;color:#cfe3ee;background:rgba(255,255,255,.07);border:1px solid rgba(255,255,255,.2);transition:all .15s}\n.tabs .tab:hover{background:rgba(255,255,255,.17);color:#fff;transform:translateY(-1px)}\n.tabs .tab svg{width:21px;height:21px;flex:none}\n.tabs .tab .tt{line-height:1.2}\n.tabs .tab b{display:block;font-size:13px}\n.tabs .tab.on{background:#fff;color:#12384f;border-color:#fff;box-shadow:0 4px 14px rgba(0,0,0,.28)}\n.tt3 th,.tt3 td{text-align:left;white-space:normal}.tt3 td:last-child{font-weight:600;white-space:nowrap}\n.cx{background:#eef5fa;border-left:4px solid #12384f;border-radius:6px;padding:8px 14px}\n</style>\n</head><body>\n<header><h1>Controle de qualidade GNSS (estilo TEQC)</h1><span>Completude, multipath, SNR e saltos de ciclo · GPS L1/L2</span>\n<nav class="tabs"><a class="tab" href="/" title="Posição de satélites: efemérides transmitidas × precisas"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="3.2"/><ellipse cx="12" cy="12" rx="10" ry="4.2" transform="rotate(-30 12 12)"/><circle cx="19.2" cy="7.8" r="1.3" fill="currentColor"/></svg><div class="tt"><b>Efemérides</b></div></a><a class="tab" href="/obs" title="Qualidade das observáveis L1/L2 e saltos de ciclo"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"><path d="M2 12h3.5l2.5-7 4 14 3-10 2 3H22"/></svg><div class="tt"><b>Observáveis</b></div></a><a class="tab on" href="/qc" title="Completude, multipath, SNR e saltos de ciclo"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"><path d="M12 3l7 3v5c0 4.5-3 8-7 10-4-2-7-5.5-7-10V6z"/><path d="M8.5 12.2l2.5 2.5 4.5-5"/></svg><div class="tt"><b>Qualidade (TEQC)</b></div></a><a class="tab" href="/rinex" title="Cortar sessões, filtrar GPS e L1/C1 (como o teqc)"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"><circle cx="6" cy="6.5" r="2.4"/><circle cx="6" cy="17.5" r="2.4"/><path d="M8 8l12 8M8 16L20 8"/></svg><div class="tt"><b>Editar RINEX</b></div></a><a class="tab" href="/ppp" title="Resultados do IBGE-PPP: σ3D, convergência, comparações"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="8"/><circle cx="12" cy="12" r="3"/><path d="M12 2v4M12 18v4M2 12h4M18 12h4"/></svg><div class="tt"><b>PPP (IBGE)</b></div></a><a class="tab" href="/polo" title="xp, yp a partir do Boletim B do IERS"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="9"/><path d="M12 3v18M3 12h18" opacity=".45"/><path d="M12 12c1.5-3 4.5-3.2 4.5-.5S13 14 12.2 11"/><circle cx="15" cy="9.5" r="1.3" fill="currentColor"/></svg><div class="tt"><b>Movimento do polo</b></div></a><a class="tab" href="/tempo" title="UTC, UT1, TAI, TGPS, TT, Data Juliana, semana GPS"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="9"/><path d="M12 6.5V12l3.5 2.2"/></svg><div class="tt"><b>Sistemas de tempo</b></div></a></nav></header>\n<main>\n{% for m in get_flashed_messages() %}<div class="aviso erro">{{ m }}</div>{% endfor %}\n<section class="card"><details {{ \'open\' if not sid }} class="kpinfo" style="background:#eef5fa;border-left:4px solid #12384f;border-radius:6px;padding:8px 14px">\n<summary><b>O que é o TEQC e o que esta aba calcula</b></summary>\n<p>O <b>TEQC</b> (<i>Translation, Editing and Quality Check</i>, da UNAVCO) é um programa clássico, executável, para tratar e checar a qualidade de dados GNSS. Esta aba reimplementa em Python a parte de <b>controle de qualidade (+qc)</b>, para GPS L1/L2:</p>\n<ul><li><b>Completude:</b> observações completas (fase L1 e L2 + código C1) ÷ esperadas acima da máscara de elevação. A elevação vem das efemérides transmitidas e da posição no cabeçalho do RINEX.</li>\n<li><b>Multipath MP1 e MP2:</b> RMS, após retirar o viés de cada arco contínuo (Estey &amp; Meertens, 1999).</li>\n<li><b>SNR médio</b> (SN1, SN2) e <b>saltos de ciclo</b>: variação brusca do atraso ionosférico (IOD) ou do multipath. <i>Obs. por salto</i> = observações completas ÷ saltos.</li></ul>\n<p><b>Atenção:</b> não é o executável original. Os números podem diferir levemente dos do TEQC, e os limiares de salto (IOD e MP) são valores adotados aqui e podem ser ajustados.</p></details></section>\n{% if not sid %}\n<section class="card"><h2>1. Carregar arquivos</h2>\n<form action="{{ url_for(\'qc_enviar\') }}" method="post" enctype="multipart/form-data">\n<label>Arquivos de observação (.zip do IBGE, .d/.o, .gz): pode selecionar vários<input type="file" name="arquivos" multiple required></label>\n<label>Arquivo de navegação (opcional; se o .zip já tiver o .n, ele é usado sozinho)<input type="file" name="nav"></label>\n<p>Sem navegação não há elevação, então ficam indisponíveis a completude, o mapa do céu e as estatísticas acima da máscara.</p>\n<div class="acoes"><button>Processar</button></div></form></section>\n{% else %}\n<section class="card"><h2>2. Parâmetros</h2>\n<form method="post"><div class="grade">\n<label>Arquivo<select name="arq">{% for i,n,e in arqs %}<option value="{{ i }}" {{ \'selected\' if i==res.idx }}>{{ e }} · {{ n }}</option>{% endfor %}</select></label>\n<label>Satélite (séries)<select name="sat">{% for s in sats %}<option {{ \'selected\' if s==res.sat }}>{{ s }}</option>{% endfor %}</select></label>\n<label>Máscara de elevação (°)<input type="number" name="mask" step="1" min="0" max="45" value="{{ res.par.mask|int }}"></label>\n<label>Limiar de salto IOD (cm/min)<input type="number" name="iod" step="10" min="10" value="{{ res.par.iod|int }}"></label>\n<label>Limiar de salto MP (m)<input type="number" name="mp" step="0.5" min="0.5" value="{{ res.par.mp }}"></label>\n<label>Arco mínimo (épocas)<input type="number" name="arco" step="1" min="2" value="{{ res.par.arco }}"></label></div>\n<div class="grade"><label>Receptor (digite se o arquivo não trouxer o nome)<input name="rec_nome" value="{{ res.info.dig_rec }}" placeholder="ex.: modelo do receptor"></label>\n<label>Antena (digite se o arquivo não trouxer o nome)<input name="ant_nome" value="{{ res.info.dig_ant }}" placeholder="ex.: modelo da antena"></label></div>\n<p>Cabeçalho do RINEX: receptor <b>{{ res.info.rec }}</b> (nº {{ res.info.rec_num }}, firmware {{ res.info.rec_ver }}) · antena <b>{{ res.info.ant }}</b> (nº {{ res.info.ant_num }}) · altura da antena {{ res.info.altura }} · observador/agência: {{ res.info.observador }} · programa: {{ res.info.pgm }}</p>\n{% if res.info.vazio_rec or res.info.vazio_ant %}<div class="aviso">O próprio arquivo diz <b>"{{ res.info.rec }}"</b> / <b>"{{ res.info.ant }}"</b>: o conversor não preencheu o modelo. O app mostra o que está no cabeçalho. Digite os nomes acima e clique em Atualizar, ou corrija o cabeçalho do RINEX (linhas <code>REC # / TYPE / VERS</code> e <code>ANT # / TYPE</code>).</div>{% endif %}\n{% if not res.tem_el %}<div class="aviso">Sem arquivo de navegação para este arquivo: elevação, completude por elevação e mapa do céu indisponíveis.</div>{% endif %}\n<div class="acoes"><button>Atualizar</button><a class="btn sec" href="{{ url_for(\'qc_index\') }}">Trocar arquivos</a></div></form></section>\n<section class="card"><h2>3. Resumo por arquivo</h2>\n<div class="rolar"><table><tr>{% for c in cab_res %}<th>{{ c }}</th>{% endfor %}</tr>\n{% for r in res.resumo %}<tr>{% for c in r %}<td>{{ c }}</td>{% endfor %}</tr>{% endfor %}</table></div>\n<h3>Por satélite — {{ res.nome }}</h3>\n<div class="rolar"><table><tr>{% for c in cab_sat %}<th>{{ c }}</th>{% endfor %}</tr>\n{% for r in res.sats %}<tr>{% for c in r %}<td>{{ c }}</td>{% endfor %}</tr>{% endfor %}</table></div>\n<div class="acoes"><a class="btn" href="{{ url_for(\'qc_baixar\', sid=sid, what=\'resumo\') }}">Baixar resumo (CSV)</a>\n<a class="btn" href="{{ url_for(\'qc_baixar\', sid=sid, what=\'sats\') }}">Baixar tabela por satélite (CSV)</a></div>\n{% for t,b in res.figs %}<h3>{{ t }}</h3><figure><img src="data:image/png;base64,{{ b }}" alt="{{ t }}">\n<a class="btn sec" href="{{ url_for(\'qc_baixar\', sid=sid, what=\'g\' ~ loop.index) }}">Baixar PNG</a></figure>{% endfor %}</section>\n{% endif %}\n</main></body></html>\n',
    'rinex': '<!doctype html>\n<html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">\n<title>Editar RINEX (corte, constelação e observáveis)</title>\n<link rel="stylesheet" href="{{ url_for(\'static\', filename=\'estilo.css\') }}">\n<style>\n.tabs{display:flex;gap:7px;margin-top:14px;flex-wrap:wrap}\n.tabs .tab{display:flex;align-items:center;gap:8px;padding:8px 13px 8px 10px;border-radius:12px;text-decoration:none;color:#cfe3ee;background:rgba(255,255,255,.07);border:1px solid rgba(255,255,255,.2);transition:all .15s}\n.tabs .tab:hover{background:rgba(255,255,255,.17);color:#fff;transform:translateY(-1px)}\n.tabs .tab svg{width:21px;height:21px;flex:none}\n.tabs .tab .tt{line-height:1.2}\n.tabs .tab b{display:block;font-size:13px}\n.tabs .tab.on{background:#fff;color:#12384f;border-color:#fff;box-shadow:0 4px 14px rgba(0,0,0,.28)}\n.tt3 th,.tt3 td{text-align:left;white-space:normal}.tt3 td:last-child{font-weight:600;white-space:nowrap}\n.cx{background:#eef5fa;border-left:4px solid #12384f;border-radius:6px;padding:8px 14px}\n</style>\n</head><body>\n<header><h1>Editar RINEX (corte, constelação e observáveis)</h1><span>Equivalente ao teqc -st/-e, -R -E -C e -O.obs · Trabalho Prático II</span>\n<nav class="tabs"><a class="tab" href="/" title="Posição de satélites: efemérides transmitidas × precisas"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="3.2"/><ellipse cx="12" cy="12" rx="10" ry="4.2" transform="rotate(-30 12 12)"/><circle cx="19.2" cy="7.8" r="1.3" fill="currentColor"/></svg><div class="tt"><b>Efemérides</b></div></a><a class="tab" href="/obs" title="Qualidade das observáveis L1/L2 e saltos de ciclo"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"><path d="M2 12h3.5l2.5-7 4 14 3-10 2 3H22"/></svg><div class="tt"><b>Observáveis</b></div></a><a class="tab" href="/qc" title="Completude, multipath, SNR e saltos de ciclo"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"><path d="M12 3l7 3v5c0 4.5-3 8-7 10-4-2-7-5.5-7-10V6z"/><path d="M8.5 12.2l2.5 2.5 4.5-5"/></svg><div class="tt"><b>Qualidade (TEQC)</b></div></a><a class="tab on" href="/rinex" title="Cortar sessões, filtrar GPS e L1/C1 (como o teqc)"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"><circle cx="6" cy="6.5" r="2.4"/><circle cx="6" cy="17.5" r="2.4"/><path d="M8 8l12 8M8 16L20 8"/></svg><div class="tt"><b>Editar RINEX</b></div></a><a class="tab" href="/ppp" title="Resultados do IBGE-PPP: σ3D, convergência, comparações"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="8"/><circle cx="12" cy="12" r="3"/><path d="M12 2v4M12 18v4M2 12h4M18 12h4"/></svg><div class="tt"><b>PPP (IBGE)</b></div></a><a class="tab" href="/polo" title="xp, yp a partir do Boletim B do IERS"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="9"/><path d="M12 3v18M3 12h18" opacity=".45"/><path d="M12 12c1.5-3 4.5-3.2 4.5-.5S13 14 12.2 11"/><circle cx="15" cy="9.5" r="1.3" fill="currentColor"/></svg><div class="tt"><b>Movimento do polo</b></div></a><a class="tab" href="/tempo" title="UTC, UT1, TAI, TGPS, TT, Data Juliana, semana GPS"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="9"/><path d="M12 6.5V12l3.5 2.2"/></svg><div class="tt"><b>Sistemas de tempo</b></div></a></nav></header>\n<main>\n{% for m in get_flashed_messages() %}<div class="aviso erro">{{ m }}</div>{% endfor %}\n\n<section class="card"><details {{ \'open\' if not sid }} class="cx">\n<summary><b>O que esta aba faz</b></summary>\n<p>Prepara os arquivos do trabalho de PPP sem usar o <code>teqc.exe</code>. A partir do RINEX de 2 h de cada cenário, gera:</p>\n<ul><li><b>Sessões de 5 min, 30 min, 1 h e 2 h</b> (equivale a <code>teqc -st … -e …</code>), a partir da primeira época ou de um horário que você escolher. Os limites são inclusivos e estão no tempo do próprio arquivo (GPS/UTC).</li>\n<li><b>Versão GPS com L1 e C1</b> (equivale a <code>teqc -R -E -C -O.obs L1,C1</code>): retira GLONASS, Galileo, BeiDou e SBAS e mantém só as observáveis escolhidas. Satélites sem dado nessas observáveis são removidos.</li>\n<li>Opcional: <b>versão GPS com L1/L2</b>, para comparar L1 pura × dupla frequência com a mesma constelação.</li></ul>\n<p>Os nomes de saída seguem o padrão do roteiro (ex.: <code>CEN1_30MIN.26o</code>, <code>CEN1_2H_L1_GPS.26o</code>), sem espaços nem caracteres especiais. Funciona com RINEX 2.xx (também descompacta Hatanaka). Os arquivos editados são conferidos relendo-os, mas confirme o resultado no seu processamento.</p></details></section>\n{% if not sid %}\n<section class="card"><h2>1. Arquivos e parâmetros</h2>\n<form action="{{ url_for(\'rinex_processar\') }}" method="post" enctype="multipart/form-data">\n<label>RINEX de observação de 2 h (.26o, .zip ou .gz). Pode enviar os três cenários de uma vez; o prefixo vem do nome do arquivo<input type="file" name="arquivos" multiple required></label>\n<div class="grade">\n<label>Prefixo dos arquivos de saída (só vale para um arquivo; ex.: CEN1)<input name="prefixo" placeholder="vazio = usa o nome do arquivo"></label>\n<label>Início das sessões (no tempo do arquivo; vazio = 1ª época)<input type="datetime-local" step="1" name="inicio"></label>\n<label>Durações (minutos, separadas por vírgula)<input name="duracoes" value="5,30,60,120"></label>\n<label>Constelações mantidas nas versões filtradas (G = GPS)<input name="sistemas" value="G"></label>\n<label>Observáveis da versão L1<input name="tipos_l1" value="L1,C1"></label>\n<label>Modelo da antena no padrão IGS (opcional; ex.: TRM57971.00     NONE)<input name="antena" placeholder="vazio = mantém o do arquivo"></label>\n<label>Altura da antena em metros (opcional)<input name="altura" placeholder="vazio = mantém o do arquivo"></label></div>\n<p>O IBGE-PPP só aplica a correção do centro de fase da antena se o modelo estiver no padrão do IGS. Arquivos de conversores costumam trazer <code>UNKNOWN</code>; se for o seu caso, informe aqui o modelo (da caderneta de campo) e a altura, que são gravados no cabeçalho de todos os arquivos gerados.</p>\n<label class="chk"><input type="checkbox" name="completa" checked> Recorte completo, sem filtro (4 arquivos por cenário)</label>\n<label class="chk"><input type="checkbox" name="l1" checked> Versão GPS L1 + C1 (como o item 4.3 do roteiro)</label>\n<label class="chk"><input type="checkbox" name="dupla"> Versão GPS L1/L2 (para comparar com a L1 pura)</label>\n<div class="acoes"><button>Gerar arquivos</button></div></form></section>\n{% else %}\n<section class="card"><h2>2. Arquivos de entrada</h2>\n<div class="rolar"><table><tr><th>Arquivo</th><th>Épocas</th><th>Primeira época</th><th>Última época</th><th>Intervalo (s)</th><th>Observáveis</th></tr>\n{% for e in entradas %}<tr><td>{{ e.nome }}</td><td>{{ e.n }}</td><td>{{ e.ini.strftime(\'%d/%m/%Y %H:%M:%S\') }}</td><td>{{ e.fim.strftime(\'%d/%m/%Y %H:%M:%S\') }}</td><td>{{ \'%g\'|format(e.passo) }}</td><td>{{ e.tipos }}</td></tr>{% endfor %}</table></div></section>\n<section class="card"><h2>3. Arquivos gerados ({{ linhas|length }})</h2>\n<div class="acoes"><a class="btn" href="{{ url_for(\'rinex_baixar\', sid=sid, nome=\'todos.zip\') }}">Baixar todos (.zip)</a><a class="btn sec" href="{{ url_for(\'rinex_index\') }}">Novo processamento</a></div>\n<div class="rolar"><table><tr><th>Arquivo</th><th>Descrição</th><th>Épocas</th><th>Início</th><th>Fim</th><th>Satélites</th><th>Observáveis</th><th>KB</th><th></th></tr>\n{% for l in linhas %}<tr><td>{{ l.nome }}</td><td>{{ l.desc }}</td><td>{{ l.ep }}</td><td>{{ l.ini.strftime(\'%H:%M:%S\') }}</td><td>{{ l.fim.strftime(\'%H:%M:%S\') }}</td><td>{{ l.sats }}</td><td>{{ l.tipos }}</td><td>{{ \'%.0f\'|format(l.kb) }}</td>\n<td><a href="{{ url_for(\'rinex_baixar\', sid=sid, nome=l.nome) }}">baixar</a></td></tr>{% endfor %}</table></div>\n<p>Próximo passo do roteiro: enviar cada arquivo ao IBGE-PPP (modo estático, altura e modelo da antena da caderneta) e, quando receber os resultados, abrir a aba <b>PPP (IBGE)</b>.</p></section>\n{% endif %}\n\n</main></body></html>\n',
    'ppp': '<!doctype html>\n<html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">\n<title>PPP (IBGE): resultados e comparações</title>\n<link rel="stylesheet" href="{{ url_for(\'static\', filename=\'estilo.css\') }}">\n<style>\n.tabs{display:flex;gap:7px;margin-top:14px;flex-wrap:wrap}\n.tabs .tab{display:flex;align-items:center;gap:8px;padding:8px 13px 8px 10px;border-radius:12px;text-decoration:none;color:#cfe3ee;background:rgba(255,255,255,.07);border:1px solid rgba(255,255,255,.2);transition:all .15s}\n.tabs .tab:hover{background:rgba(255,255,255,.17);color:#fff;transform:translateY(-1px)}\n.tabs .tab svg{width:21px;height:21px;flex:none}\n.tabs .tab .tt{line-height:1.2}\n.tabs .tab b{display:block;font-size:13px}\n.tabs .tab.on{background:#fff;color:#12384f;border-color:#fff;box-shadow:0 4px 14px rgba(0,0,0,.28)}\n.tt3 th,.tt3 td{text-align:left;white-space:normal}.tt3 td:last-child{font-weight:600;white-space:nowrap}\n.cx{background:#eef5fa;border-left:4px solid #12384f;border-radius:6px;padding:8px 14px}\n</style>\n</head><body>\n<header><h1>PPP (IBGE): resultados e comparações</h1><span>σ3D, tempo de convergência e gráficos do Trabalho Prático II</span>\n<nav class="tabs"><a class="tab" href="/" title="Posição de satélites: efemérides transmitidas × precisas"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="3.2"/><ellipse cx="12" cy="12" rx="10" ry="4.2" transform="rotate(-30 12 12)"/><circle cx="19.2" cy="7.8" r="1.3" fill="currentColor"/></svg><div class="tt"><b>Efemérides</b></div></a><a class="tab" href="/obs" title="Qualidade das observáveis L1/L2 e saltos de ciclo"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"><path d="M2 12h3.5l2.5-7 4 14 3-10 2 3H22"/></svg><div class="tt"><b>Observáveis</b></div></a><a class="tab" href="/qc" title="Completude, multipath, SNR e saltos de ciclo"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"><path d="M12 3l7 3v5c0 4.5-3 8-7 10-4-2-7-5.5-7-10V6z"/><path d="M8.5 12.2l2.5 2.5 4.5-5"/></svg><div class="tt"><b>Qualidade (TEQC)</b></div></a><a class="tab" href="/rinex" title="Cortar sessões, filtrar GPS e L1/C1 (como o teqc)"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"><circle cx="6" cy="6.5" r="2.4"/><circle cx="6" cy="17.5" r="2.4"/><path d="M8 8l12 8M8 16L20 8"/></svg><div class="tt"><b>Editar RINEX</b></div></a><a class="tab on" href="/ppp" title="Resultados do IBGE-PPP: σ3D, convergência, comparações"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="8"/><circle cx="12" cy="12" r="3"/><path d="M12 2v4M12 18v4M2 12h4M18 12h4"/></svg><div class="tt"><b>PPP (IBGE)</b></div></a><a class="tab" href="/polo" title="xp, yp a partir do Boletim B do IERS"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="9"/><path d="M12 3v18M3 12h18" opacity=".45"/><path d="M12 12c1.5-3 4.5-3.2 4.5-.5S13 14 12.2 11"/><circle cx="15" cy="9.5" r="1.3" fill="currentColor"/></svg><div class="tt"><b>Movimento do polo</b></div></a><a class="tab" href="/tempo" title="UTC, UT1, TAI, TGPS, TT, Data Juliana, semana GPS"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="9"/><path d="M12 6.5V12l3.5 2.2"/></svg><div class="tt"><b>Sistemas de tempo</b></div></a></nav></header>\n<main>\n{% for m in get_flashed_messages() %}<div class="aviso erro">{{ m }}</div>{% endfor %}\n\n<section class="card"><details {{ \'open\' if not sid }} class="cx">\n<summary><b>O que esta aba faz</b></summary>\n<p>O processamento do <b>IBGE-PPP</b> é feito no portal do IBGE (com seu e-mail) e não pode ser automatizado. Esta aba <b>lê o resultado</b> que o IBGE devolve (o .zip, ou os arquivos .sum e .pos) e faz a parte analítica do roteiro:</p>\n<ul><li><b>σ3D = √(σφ² + σλ² + σh²)</b>, com os sigmas da seção 3.3 do arquivo .sum.</li>\n<li><b>Tempo de convergência</b>, calculado no .pos (σ3D menor que 1 m e menor que 0,1 m, e permanecendo assim) e as <b>curvas de desvio padrão e de convergência</b> época a época, equivalentes aos gráficos do PDF.</li>\n<li><b>Gráficos comparativos:</b> tempo de rastreio × sigmas para cada cenário e L1 pura × L1/L2.</li></ul>\n<p>Nomeie os arquivos de entrada de forma que o sistema reconheça o cenário e a duração, por exemplo <code>CEN1_30MIN</code> e <code>CEN1_30MIN_L1_GPS</code>; tudo pode ser corrigido na tabela da tela seguinte. O modo (L1 ou L1/L2) vem do próprio .sum.</p>\n<p><b>Atenção:</b> o leitor segue o formato descrito no manual do IBGE-PPP. Se algum campo não for reconhecido, digite os valores na tabela manual abaixo; o gráfico de convergência depende do .pos.</p></details></section>\n{% if not sid %}\n<section class="card"><h2>1. Resultados do IBGE-PPP</h2>\n<form action="{{ url_for(\'ppp_enviar\') }}" method="post" enctype="multipart/form-data">\n<label>Arquivos .zip do IBGE-PPP (ou .sum e .pos): selecione todos de uma vez<input type="file" name="arquivos" multiple></label>\n<label>Ou digite manualmente (uma linha por processamento: <code>cenário;duração em min;modo;σφ;σλ;σh;convergência em min (opcional)</code>)\n<textarea name="manual" rows="5" style="width:100%;margin-top:4px;padding:8px;border:1px solid #c5ccd6;border-radius:6px;font:13px monospace" placeholder="1;30;L1/L2;0,0120;0,0150;0,0400;12&#10;1;30;L1;0,35;0,42;0,90"></textarea></label>\n<div class="acoes"><button>Ler resultados</button></div></form></section>\n{% else %}\n<section class="card"><h2>2. Identificação de cada processamento</h2>\n<form method="post"><div class="rolar"><table><tr><th>Arquivo</th><th>Cenário</th><th>Duração (min)</th><th>Modo</th><th>Leitura</th></tr>\n{% for it in itens %}{% set i = loop.index0 %}<tr><td>{{ it.nome }}</td>\n<td><select name="cen{{ i }}"><option value="">—</option>{% for c in (1,2,3) %}<option value="{{ c }}" {{ \'selected\' if it.rot.cen==c }}>{{ c }}</option>{% endfor %}</select></td>\n<td><input name="dur{{ i }}" value="{{ \'%g\'|format(it.rot.dur) if it.rot.dur else \'\' }}" style="width:90px"></td>\n<td><select name="modo{{ i }}"><option value="">—</option>{% for m in (\'L1/L2\',\'L1\') %}<option {{ \'selected\' if it.rot.modo==m }}>{{ m }}</option>{% endfor %}</select></td>\n<td style="text-align:left;white-space:normal">{% if it.erro %}<span style="color:#b71c1c">{{ it.erro }}</span>{% else %}.sum {{ \'ok\' if it.sum else \'—\' }} · .pos {{ \'ok (\' ~ it.pos.n ~ \' épocas)\' if it.pos else \'—\' }}{% endif %}</td></tr>{% endfor %}</table></div>\n{% if com_pos %}<label style="margin-top:10px">Processamento para as curvas época a época<select name="curva">{% for i in com_pos %}<option value="{{ i }}" {{ \'selected\' if i==curva }}>{{ itens[i].nome }}</option>{% endfor %}</select></label>{% endif %}\n<div class="acoes"><button>Atualizar</button><a class="btn sec" href="{{ url_for(\'ppp_index\') }}">Novos arquivos</a></div></form></section>\n<section class="card"><h2>3. Resultados</h2>\n<div class="rolar"><table><tr>{% for c in cab %}<th>{{ c }}</th>{% endfor %}</tr>{% for r in tab %}<tr>{% for c in r %}<td>{{ c }}</td>{% endfor %}</tr>{% endfor %}</table></div>\n<div class="acoes"><a class="btn" href="{{ url_for(\'ppp_baixar\', sid=sid, what=\'csv\') }}">Baixar tabela (CSV)</a></div>\n<p>σ3D e σ plan. usam os sigmas do relatório (seção 3.3 do .sum). Como o próprio IBGE ressalta, o desvio padrão é um indicador otimista; no relatório, compare também com a diferença para uma coordenada conhecida, se houver.</p>\n{% for t,b in figs %}<h3>{{ t }}</h3><figure><img src="data:image/png;base64,{{ b }}" alt="{{ t }}"><a class="btn sec" href="{{ url_for(\'ppp_baixar\', sid=sid, what=\'g\' ~ loop.index) }}">Baixar PNG</a></figure>{% endfor %}</section>\n{% endif %}\n\n</main></body></html>\n',
    'polo': '<!doctype html>\n<html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">\n<title>Movimento do polo</title>\n<link rel="stylesheet" href="{{ url_for(\'static\', filename=\'estilo.css\') }}">\n<style>\n.tabs{display:flex;gap:7px;margin-top:14px;flex-wrap:wrap}\n.tabs .tab{display:flex;align-items:center;gap:8px;padding:8px 13px 8px 10px;border-radius:12px;text-decoration:none;color:#cfe3ee;background:rgba(255,255,255,.07);border:1px solid rgba(255,255,255,.2);transition:all .15s}\n.tabs .tab:hover{background:rgba(255,255,255,.17);color:#fff;transform:translateY(-1px)}\n.tabs .tab svg{width:21px;height:21px;flex:none}\n.tabs .tab .tt{line-height:1.2}\n.tabs .tab b{display:block;font-size:13px}\n.tabs .tab.on{background:#fff;color:#12384f;border-color:#fff;box-shadow:0 4px 14px rgba(0,0,0,.28)}\n.tt3 th,.tt3 td{text-align:left;white-space:normal}.tt3 td:last-child{font-weight:600;white-space:nowrap}\n.cx{background:#eef5fa;border-left:4px solid #12384f;border-radius:6px;padding:8px 14px}\n</style>\n</head><body>\n<header><h1>Movimento do polo</h1><span>Coordenadas do polo (xp, yp) do IERS em torno de um evento · Aula 4</span>\n<nav class="tabs"><a class="tab" href="/" title="Posição de satélites: efemérides transmitidas × precisas"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="3.2"/><ellipse cx="12" cy="12" rx="10" ry="4.2" transform="rotate(-30 12 12)"/><circle cx="19.2" cy="7.8" r="1.3" fill="currentColor"/></svg><div class="tt"><b>Efemérides</b></div></a><a class="tab" href="/obs" title="Qualidade das observáveis L1/L2 e saltos de ciclo"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"><path d="M2 12h3.5l2.5-7 4 14 3-10 2 3H22"/></svg><div class="tt"><b>Observáveis</b></div></a><a class="tab" href="/qc" title="Completude, multipath, SNR e saltos de ciclo"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"><path d="M12 3l7 3v5c0 4.5-3 8-7 10-4-2-7-5.5-7-10V6z"/><path d="M8.5 12.2l2.5 2.5 4.5-5"/></svg><div class="tt"><b>Qualidade (TEQC)</b></div></a><a class="tab" href="/rinex" title="Cortar sessões, filtrar GPS e L1/C1 (como o teqc)"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"><circle cx="6" cy="6.5" r="2.4"/><circle cx="6" cy="17.5" r="2.4"/><path d="M8 8l12 8M8 16L20 8"/></svg><div class="tt"><b>Editar RINEX</b></div></a><a class="tab" href="/ppp" title="Resultados do IBGE-PPP: σ3D, convergência, comparações"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="8"/><circle cx="12" cy="12" r="3"/><path d="M12 2v4M12 18v4M2 12h4M18 12h4"/></svg><div class="tt"><b>PPP (IBGE)</b></div></a><a class="tab on" href="/polo" title="xp, yp a partir do Boletim B do IERS"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="9"/><path d="M12 3v18M3 12h18" opacity=".45"/><path d="M12 12c1.5-3 4.5-3.2 4.5-.5S13 14 12.2 11"/><circle cx="15" cy="9.5" r="1.3" fill="currentColor"/></svg><div class="tt"><b>Movimento do polo</b></div></a><a class="tab" href="/tempo" title="UTC, UT1, TAI, TGPS, TT, Data Juliana, semana GPS"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="9"/><path d="M12 6.5V12l3.5 2.2"/></svg><div class="tt"><b>Sistemas de tempo</b></div></a></nav></header>\n<main>\n{% for m in get_flashed_messages() %}<div class="aviso erro">{{ m }}</div>{% endfor %}\n\n<section class="card"><details {{ \'open\' if not sid }} style="background:#eef5fa;border-left:4px solid #12384f;border-radius:6px;padding:8px 14px">\n<summary><b>O que é o movimento do polo e o que esta aba faz</b></summary>\n<p>O <b>movimento do polo</b> é a variação do eixo de rotação instantâneo da Terra em relação ao pólo convencional (CIO), descrita por <b>xp</b> e <b>yp</b>, em milissegundos de arco (mas). Vem do IERS (Boletim B, valores finais) e inclui o período de Chandler (~433 dias) e o movimento anual. Aqui, dado um evento (por exemplo, um terremoto), a aba usa de 6 meses antes a 6 meses depois e calcula, como na aula:</p>\n<ul><li><b>Coordenadas polares:</b> d = √(xp² + yp²) e θ = atan2(yp, xp), de modo que xp = d·cosθ e yp = d·senθ (atan2 resolve o quadrante).</li>\n<li><b>Distância linear:</b> d (mas) → radianos → metros com o raio médio (6371 km). Vale 1 mas ≈ 3,09 cm.</li>\n<li><b>Média móvel</b> e <b>variação diária</b>, comparação <b>antes × depois</b> e um <b>indicador de descontinuidade</b> no dia do evento.</li>\n<li><b>Gráficos:</b> xp e yp separados, trajetória xp × yp, polar (θ, d) e 3D (Z = tempo).</li></ul></details></section>\n{% if not sid %}\n<section class="card"><h2>1. Boletins do IERS</h2>\n<form action="{{ url_for(\'polo_enviar\') }}" method="post" enctype="multipart/form-data">\n<label>Boletins B (.txt, ou um .zip com eles): pode selecionar vários<input type="file" name="arquivos" multiple></label>\n<div class="grade"><label>Evento (data do terremoto, UTC)<input type="date" id="evento" name="evento" required></label>\n<label>Exemplos (confira data e magnitude no catálogo do USGS)<select onchange="document.getElementById(\'evento\').value=this.value"><option value="">escolher…</option>{% for n,d in eventos %}<option value="{{ d }}">{{ n }} · {{ d }}</option>{% endfor %}</select></label>\n<label>Meses antes e depois<input type="number" name="meses" value="6" min="1" max="24"></label></div>\n<label class="chk"><input type="checkbox" name="baixar"> Se eu não enviar arquivos, tentar baixar do IERS (precisa de internet)</label>\n<p>Os boletins B ficam no IERS Data Center (datacenter.iers.org). O valor final de um mês sai no boletim publicado dois meses depois. Depois de informar a data, a tela seguinte lista os números dos boletins necessários.</p>\n<div class="acoes"><button>Processar</button></div></form></section>\n{% else %}\n<section class="card"><h2>2. Parâmetros</h2>\n<p>Dados carregados: <b>{{ info.arquivos }}</b> arquivo(s), <b>{{ info.n }}</b> dias, de <b>{{ info.ini.strftime(\'%d/%m/%Y\') if info.ini else \'—\' }}</b> a <b>{{ info.fim.strftime(\'%d/%m/%Y\') if info.fim else \'—\' }}</b> ({{ info.formatos }}).\nBoletins necessários para esta janela: <b>bulletinb-{{ info.nec[0] }}.txt a bulletinb-{{ info.nec[-1] }}.txt</b>.</p>\n<form method="post"><div class="grade">\n<label>Evento (UTC)<input type="date" id="evento" name="evento" value="{{ par.evento }}" required></label>\n<label>Exemplos<select onchange="document.getElementById(\'evento\').value=this.value"><option value="">escolher…</option>{% for n,d in eventos %}<option value="{{ d }}">{{ n }} · {{ d }}</option>{% endfor %}</select></label>\n<label>Meses antes e depois<input type="number" name="meses" value="{{ par.meses }}" min="1" max="24"></label>\n<label>Janela da média móvel (dias)<input type="number" name="ma" value="{{ par.ma }}" min="3" max="61"></label></div>\n<div class="acoes"><button>Atualizar</button><a class="btn sec" href="{{ url_for(\'polo_index\') }}">Trocar boletins</a></div></form></section>\n{% if erro %}<div class="aviso erro">{{ erro }}</div>{% endif %}\n{% if res %}{% set R=res.R %}{% set i=res.ind %}\n<section class="card"><h2>3. Resultados</h2>\n<div class="chips"><span>Período <b>{{ R.ini.strftime(\'%d/%m/%Y\') }} a {{ R.fim.strftime(\'%d/%m/%Y\') }}</b></span><span>Dias <b>{{ R.n }}</b></span><span>Dia do evento <b>{{ i.dia_evento.strftime(\'%d/%m/%Y\') }}</b></span>\n<span>Lacunas <b>{{ R.lacunas }}</b></span><span>Incerteza formal média (xp, yp) <b>{{ \'%.3f\'|format(i.xerr) }}, {{ \'%.3f\'|format(i.yerr) }} mas</b></span></div>\n<h3>Estatísticas antes × depois do evento</h3>\n<div class="rolar"><table><tr>{% for c in cab_est %}<th>{{ c }}</th>{% endfor %}</tr>{% for r in res.est %}<tr>{% for c in r %}<td>{{ c }}</td>{% endfor %}</tr>{% endfor %}</table></div>\n<h3>Indicador de descontinuidade no dia do evento</h3>\n<table class="peq"><tr><th>Grandeza</th><th>No evento (±2 d)</th><th>Restante da janela</th></tr>\n<tr><td>2ª diferença da posição (mas)</td><td>{{ \'%.3f\'|format(i.a_evento) }}</td><td>mediana {{ \'%.3f\'|format(i.a_mediana) }} · σ robusto {{ \'%.3f\'|format(i.a_sigma) }}</td></tr>\n<tr><td>Variação diária (mas/dia)</td><td>{{ \'%.2f\'|format(i.var_evento) }}</td><td>mediana {{ \'%.2f\'|format(i.var_mediana) }}</td></tr></table>\n<p><b>Razão = {{ \'%.1f\'|format(i.razao) }} σ.</b> A 2ª diferença é nula para um movimento suave, por isso um salto de posição no evento aparece como pico. Como regra prática, valores abaixo de ~3σ são compatíveis com a variação normal. Isto é um <b>indicador</b>, não uma prova de causa: o Boletim B é uma combinação suavizada, e passos de décimos de mas ficam abaixo do ruído da série (incerteza formal ≈ {{ \'%.2f\'|format(i.xerr) }} mas ≈ {{ \'%.1f\'|format(i.xerr * 0.0309) }} mm).</p>\n<div class="acoes"><a class="btn" href="{{ url_for(\'polo_baixar\', sid=sid, what=\'csv\') }}">Baixar tabela (CSV)</a><a class="btn" href="{{ url_for(\'polo_baixar\', sid=sid, what=\'boletins\') }}">Baixar os boletins (.zip)</a></div>\n{% for t,b in res.figs %}<h3>{{ t }}</h3><figure><img src="data:image/png;base64,{{ b }}" alt="{{ t }}"><a class="btn sec" href="{{ url_for(\'polo_baixar\', sid=sid, what=\'g\' ~ loop.index) }}">Baixar PNG</a></figure>{% endfor %}</section>\n{% endif %}{% endif %}\n\n</main></body></html>\n',
    'tempo': '<!doctype html>\n<html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">\n<title>Sistemas de tempo</title>\n<link rel="stylesheet" href="{{ url_for(\'static\', filename=\'estilo.css\') }}">\n<style>\n.tabs{display:flex;gap:7px;margin-top:14px;flex-wrap:wrap}\n.tabs .tab{display:flex;align-items:center;gap:8px;padding:8px 13px 8px 10px;border-radius:12px;text-decoration:none;color:#cfe3ee;background:rgba(255,255,255,.07);border:1px solid rgba(255,255,255,.2);transition:all .15s}\n.tabs .tab:hover{background:rgba(255,255,255,.17);color:#fff;transform:translateY(-1px)}\n.tabs .tab svg{width:21px;height:21px;flex:none}\n.tabs .tab .tt{line-height:1.2}\n.tabs .tab b{display:block;font-size:13px}\n.tabs .tab.on{background:#fff;color:#12384f;border-color:#fff;box-shadow:0 4px 14px rgba(0,0,0,.28)}\n.tt3 th,.tt3 td{text-align:left;white-space:normal}.tt3 td:last-child{font-weight:600;white-space:nowrap}\n.cx{background:#eef5fa;border-left:4px solid #12384f;border-radius:6px;padding:8px 14px}\n</style>\n</head><body>\n<header><h1>Sistemas de tempo</h1><span>UTC, UT1, TAI, TGPS, TT, TCG, Data Juliana e semana GPS · Aula 7</span>\n<nav class="tabs"><a class="tab" href="/" title="Posição de satélites: efemérides transmitidas × precisas"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="3.2"/><ellipse cx="12" cy="12" rx="10" ry="4.2" transform="rotate(-30 12 12)"/><circle cx="19.2" cy="7.8" r="1.3" fill="currentColor"/></svg><div class="tt"><b>Efemérides</b></div></a><a class="tab" href="/obs" title="Qualidade das observáveis L1/L2 e saltos de ciclo"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"><path d="M2 12h3.5l2.5-7 4 14 3-10 2 3H22"/></svg><div class="tt"><b>Observáveis</b></div></a><a class="tab" href="/qc" title="Completude, multipath, SNR e saltos de ciclo"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"><path d="M12 3l7 3v5c0 4.5-3 8-7 10-4-2-7-5.5-7-10V6z"/><path d="M8.5 12.2l2.5 2.5 4.5-5"/></svg><div class="tt"><b>Qualidade (TEQC)</b></div></a><a class="tab" href="/rinex" title="Cortar sessões, filtrar GPS e L1/C1 (como o teqc)"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"><circle cx="6" cy="6.5" r="2.4"/><circle cx="6" cy="17.5" r="2.4"/><path d="M8 8l12 8M8 16L20 8"/></svg><div class="tt"><b>Editar RINEX</b></div></a><a class="tab" href="/ppp" title="Resultados do IBGE-PPP: σ3D, convergência, comparações"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="8"/><circle cx="12" cy="12" r="3"/><path d="M12 2v4M12 18v4M2 12h4M18 12h4"/></svg><div class="tt"><b>PPP (IBGE)</b></div></a><a class="tab" href="/polo" title="xp, yp a partir do Boletim B do IERS"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="9"/><path d="M12 3v18M3 12h18" opacity=".45"/><path d="M12 12c1.5-3 4.5-3.2 4.5-.5S13 14 12.2 11"/><circle cx="15" cy="9.5" r="1.3" fill="currentColor"/></svg><div class="tt"><b>Movimento do polo</b></div></a><a class="tab on" href="/tempo" title="UTC, UT1, TAI, TGPS, TT, Data Juliana, semana GPS"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="9"/><path d="M12 6.5V12l3.5 2.2"/></svg><div class="tt"><b>Sistemas de tempo</b></div></a></nav></header>\n<main>\n{% for m in get_flashed_messages() %}<div class="aviso erro">{{ m }}</div>{% endfor %}\n\n<section class="card"><details open style="background:#eef5fa;border-left:4px solid #12384f;border-radius:6px;padding:8px 14px">\n<summary><b>O que esta aba calcula</b></summary>\n<p>Converte uma hora local para os sistemas de tempo da aula, com as mesmas equações: <b>UTC = HL + fuso</b>, <b>UT1 = UTC + DUT1</b>, <b>TAI = UTC + (TAI−UTC)</b>, <b>TGPS = TAI − 19 s</b>, <b>TT = TAI + 32,184 s</b>,\ne a <b>Data Juliana</b> (Leick, 1995), a <b>MJD</b>, a <b>semana</b> e o <b>dia da semana GPS</b>. O <b>DUT1</b> vem do boletim do IERS (Boletim A, B ou D); o <b>TAI−UTC</b> é preenchido pela tabela de segundos intercalados (37 s desde 2017).</p></details></section>\n<section class="card"><h2>1. Dados</h2>\n<form method="post" enctype="multipart/form-data"><div class="grade">\n<label>Hora local<input type="datetime-local" step="1" name="hl" value="{{ v.hl }}" required></label>\n<label>Fuso: horas a somar à hora local para obter UTC<input name="fuso" value="{{ v.fuso }}"></label>\n<label>DUT1 = UT1 − UTC (s)<input name="dut1" value="{{ v.dut1 }}"></label>\n<label>TAI − UTC (s): deixe vazio para usar a tabela<input name="tai" value="{{ v.tai }}"></label>\n<label>Boletim B do IERS (opcional): preenche DUT1 e TAI−UTC<input type="file" name="bol"></label></div>\n<div class="acoes"><button>Calcular</button><a class="btn sec" href="{{ url_for(\'tempo_pagina\', ex=1) }}">Exemplo resolvido da aula</a></div></form></section>\n{% if erro %}<div class="aviso erro">{{ erro }}</div>{% endif %}\n{% if res %}<section class="card"><h2>2. Resultado{% if exemplo %} (exemplo da aula: Belém, 05/07/2012 09:10:20){% endif %}</h2>\n{% for i in res.info %}<div class="aviso">{{ i }}</div>{% endfor %}\n<div class="rolar"><table class="tt3"><tr><th>Sistema</th><th>Equação</th><th>Resultado</th></tr>\n{% for a,b,c in res.tab %}<tr><td>{{ a }}</td><td>{{ b }}</td><td>{{ c }}</td></tr>{% endfor %}</table></div>\n{% if res.check %}<h3>Conferência com a resposta do slide</h3>\n<table class="peq"><tr><th>Item</th><th>Aula</th><th>Sistema</th><th></th></tr>\n{% for k,w,m,ok in res.check %}<tr><td>{{ k }}</td><td>{{ w }}</td><td>{{ m }}</td><td>{{ \'✔\' if ok else \'✘\' }}</td></tr>{% endfor %}</table>\n<p><b>{{ \'Todos os valores coincidem com o exemplo resolvido da aula.\' if res.check|selectattr(3)|list|length == res.check|length else \'Há diferenças em relação ao exemplo da aula.\' }}</b></p>{% endif %}\n<p>Semana e dia GPS são calculados pela data em tempo GPS (a aula usa a data do JD em UTC; só diferem nos segundos finais antes da meia-noite).</p></section>{% endif %}\n\n</main></body></html>\n',
}
ESTILO = '*{box-sizing:border-box}body{margin:0;font:15px/1.5 system-ui,Segoe UI,Arial,sans-serif;background:#f3f5f8;color:#1c2430}\nheader{background:#12384f;color:#fff;padding:16px 28px}header h1{margin:0;font-size:20px}header span{opacity:.8;font-size:13px}\nmain{max-width:1100px;margin:22px auto;padding:0 16px}.card{background:#fff;border-radius:10px;padding:20px 24px;margin-bottom:20px;box-shadow:0 1px 4px #0001}\nh2{margin-top:0;font-size:18px}h3{margin:22px 0 8px;font-size:15px;color:#12384f}\nlabel{display:block;font-weight:600;font-size:13px;margin-bottom:12px}input,select{display:block;width:100%;margin-top:4px;padding:8px;border:1px solid #c5ccd6;border-radius:6px;font:inherit}\n.grade{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:0 16px}.chk{display:flex;align-items:center;gap:8px;font-weight:500}.chk input{width:auto;margin:0}\nbutton,.btn{display:inline-block;background:#12384f;color:#fff;border:0;border-radius:6px;padding:9px 16px;font:inherit;cursor:pointer;text-decoration:none}\n.sec{background:#e4e9f0;color:#12384f}.acoes{display:flex;gap:10px;flex-wrap:wrap;margin-top:8px}\n.aviso{background:#fff6de;border-left:4px solid #e0a800;padding:8px 12px;margin:10px 0;border-radius:4px}.erro{background:#fde8e8;border-color:#c0392b}\n.chips{display:flex;gap:8px;flex-wrap:wrap}.chips span{background:#e8f0f6;border-radius:99px;padding:3px 12px;font-size:13px}.resumo{font-weight:600}\n.rolar{overflow-x:auto}table{border-collapse:collapse;width:100%;font-size:13px}th,td{border:1px solid #d9dee6;padding:5px 8px;text-align:right;white-space:nowrap}\nth{background:#eef2f6}td:first-child,th:first-child{text-align:left}.peq{width:auto;min-width:320px}\nfigure{margin:14px 0}img{max-width:100%;border:1px solid #d9dee6;border-radius:6px}pre{background:#10212c;color:#dbe9f2;padding:12px;border-radius:6px;overflow-x:auto;font-size:12px}\n'


def sincronizar(base):
    feitos = []
    itens = [('templates', n + '.html', t) for n, t in TEMPLATES.items()] + [('static', 'estilo.css', ESTILO)]
    for pasta, nome, texto in itens:
        d = os.path.join(base, pasta); p = os.path.join(d, nome)
        try:
            os.makedirs(d, exist_ok=True)
            atual = open(p, encoding='utf-8').read() if os.path.exists(p) else None
            if atual != texto:
                with open(p, 'w', encoding='utf-8', newline='\n') as f:
                    f.write(texto)
                feitos.append(nome)
        except OSError as e:
            print(f'Aviso: não consegui gravar {p}: {e}')
    if feitos:
        print('Telas recriadas a partir do código:', ', '.join(feitos))